                                if (result.targets?.length) {
                                    if (event.winnerx && event.winnerx.includes(result.targets[0])) {
                                        result.targets[0].gain(event.losecards, 'gain2');
                                    } else {
                                        result.targets[0].gain(event.wincards, 'gain2');
                                    }
                                }
