                            content() {
                                'step 0';
                                event.count = game.roundNumber;
                                ('step 1');
                                event.count--;
                                ('step 2');
                                var list = [];
                                for (var i in lib.card) {
                                    var info = lib.card[i];
                                    if (!lib.card[i].type || lib.card[i].type != 'trick' || info.notarget) continue;
                                    if (lib.card[i].mode) {
                                        if (typeof lib.card[i].mode == 'string' && get.mode() != lib.card[i].mode) continue;
                                        if (Array.isArray(lib.card[i].mode) && !lib.card[i].mode.includes(get.mode())) continue;
                                    }
                                    if (
                                        lib.filter.filterCard({ name: i }, player) &&
                                        game.hasPlayer(function (current) {
                                            return player.canUse({ name: i }, current) && player.canUse({ name: i }, current);
                                        }) &&
                                        info.selectTarget
                                    ) {
                                        var card = { name: i };
                                        var info = get.info(card);
                                        var targets = game.filterPlayer(function (current) {
                                            return lib.filter.filterTarget(card, player, current) && player.canUse({ name: i }, current);
                                        });
                                        if (targets.length) {
                                            targets.sort(lib.sort.seat);
                                            if (info.selectTarget != -1) {
                                                var num = info.selectTarget;
                                                if (Array.isArray(num)) {
                                                    game.checkMod(card, player, num, 'selectTarget', player);
                                                    if (num[0] <= 0 || num[1] < num[0]) continue;
                                                    if (targets.length < num[0]) continue;
                                                } else if (typeof num == 'number') {
                                                    var range = [num, num];
                                                    game.checkMod(card, player, range, 'selectTarget', player);
                                                    if (range[0] <= 0 || range[1] < range[0]) continue;
                                                    if (targets.length < range[0]) continue;
                                                } else continue;
                                            }
                                        } else continue;
                                    } else continue;
                                    list.push(i);
                                }
                                if (list && list.length) {
                                    //game.log('1');
                                    var cardsx = list.randomGet();
                                    try {
                                        var card = { name: cardsx };
                                        var info = lib.card[cardsx];
                                        var targets = game.filterPlayer(function (current) {
                                            return lib.filter.filterTarget(card, player, current) && player.canUse(card, current);
                                        });
                                        if (targets.length) {
                                            //game.log('2');
                                            game.playAudio('../extension/汤圆精品包/audio/tyj_qianhoubackground.mp3');
                                            targets.sort(lib.sort.seat);
                                            if (info.selectTarget && info.selectTarget != -1) {
                                                var num = info.selectTarget;
                                                if (Array.isArray(num)) {
                                                    game.checkMod(card, player, num, 'selectTarget', player);
                                                    if (num[0] <= 0 || num[1] < num[0] || targets.length < num[0]) {
                                                        game.log('牌的目标不符合规则');
                                                        event.finish();
                                                    } else {
                                                        var num = num[0] + Math.floor(Math.random() * (num[1] - num[0] + 1));
                                                        targets = targets.randomGets(num);
                                                        player.useCard(card, targets, 'noai').set('oncard', (card) => {
                                                            lib.skill.tyj_qianhou.trowFakeCards(player, [card.name]);
                                                        });
                                                    }
                                                } else if (typeof num == 'number') {
                                                    var range = [num, num];
                                                    game.checkMod(card, player, range, 'selectTarget', player);
                                                    if (range[0] <= 0 || range[1] < range[0] || targets.length < range[0]) {
                                                        game.log('牌的目标不符合规则');
                                                        event.finish();
                                                    } else {
                                                        range = range[0] + Math.floor(Math.random() * (range[1] - range[0] + 1));
                                                        targets = targets.randomGets(range);
                                                        player.useCard(card, targets, 'noai').set('oncard', (card) => {
                                                            lib.skill.tyj_qianhou.trowFakeCards(player, [card.name]);
                                                        });
                                                    }
                                                } else game.log('因为没有目标,所以没用');
                                                //测试 game.me.addSkill('tyj_qianhou');
                                            } else {
                                                player.useCard(card, targets, 'noai').set('oncard', (card) => {
                                                    lib.skill.tyj_qianhou.trowFakeCards(player, [card.name]);
                                                });
                                            }
                                        } else {
                                            game.log('没用合法目标');
                                            game.log(cardsx);
                                        }
                                    } catch (e) {
                                        game.log('有一张无法使用的锦囊牌消耗了一次', '#g【千喉】');
                                        player.popup('无法使用');
                                        event.goto(3);
                                    }
                                } else game.log('没用找到符合条件的牌');
                                //game.log('执行完第'+event.count+'次');
                                ('step 3');
                                if (event.count > 0 && player.isAlive()) {
                                    event.goto(1);
                                }
                            },
