                                        if (player.storage['tyj_qieyong_' + get.translation(target)] && player.storage['tyj_qieyong_' + get.translation(target)] > 0) return [player.storage['tyj_qieyong_' + get.translation(target)] + 1, -(player.storage['tyj_qieyong_' + get.translation(target)] * 2 + 1)];
