                                    if (event.cardst && get.position(event.cardst, true) == 'd' && event.loserx.hasUseTarget(event.cardst)) {
                                        event.loserx.$gain2(event.cardst, false);
                                        event.loserx.chooseUseTarget(event.cardst, '营说:选择' + get.translation(event.cardst) + '的使用目标', true).set('prompt2', get.translation(event.name + '_info'));
                                    }
