                        tyj_jiangling: {
                            trigger: {
                                player: 'phaseZhunbeiBegin',
                            },
                            limited: true,
                            audio: 'ext:汤圆精品包/audio:4',
                            check(event, player) {
                                return (
                                    game.hasPlayer(function (current) {
                                        return current.inRangeOf(player) && current.hp + current.hujia <= 4 && get.attitude(current, player) < 0;
                                    }) &&
                                    player.countCards('hs', function (card) {
                                        return card.name == 'sha';
                                    }) > 0
                                );
                            },
                            filter(event, player) {
                                return true;
                            },
                            content() {
                                'step 0';
                                player.awakenSkill('tyj_jiangling');
                                if (!player.storage.tyj_jiangling_bonus) {
                                    player.storage.tyj_jiangling_bonus = 0;
                                }
                                player.storage.tyj_jiangling_bonus++;
                                if (player.storage.tyj_jiangling_bonus && player.storage.tyj_jiangling_bonus > 0) {
                                    player.gainMaxHp();
                                    player.changeHp(1);
                                }
                                var list = ['杀伤害基数', '杀目标上限', '杀造成伤害后摸牌数'];
                                player
                                    .chooseControl(list)
                                    .set('prompt', '痛汲:选择令你以下一项数值本回合+1')
                                    .set('ai', function () {
                                        var num = Math.random();
                                        if (num < 0.8) {
                                            var numx = Math.random();
                                            if (numx < 0.65) {
                                                return '杀伤害基数';
                                            }
                                            return '杀目标上限';
                                        }
                                        return '杀造成伤害后摸牌数';
                                    });
                                ('step 1');
                                if (result.control) {
                                    if (result.control == '杀伤害基数') {
                                        if (!player.storage.tyj_jiangling_shadamage) {
                                            player.storage.tyj_jiangling_shadamage = 0;
                                        }
                                        player.storage.tyj_jiangling_shadamage++;
                                    } else if (result.control == '杀目标上限') {
                                        if (!player.storage.tyj_jiangling_shatarget) {
                                            player.storage.tyj_jiangling_shatarget = 0;
                                        }
                                        player.storage.tyj_jiangling_shatarget++;
                                    } else if (result.control == '杀造成伤害后摸牌数') {
                                        if (!player.storage.tyj_jiangling_shadraw) {
                                            player.storage.tyj_jiangling_shadraw = 0;
                                        }
                                        player.storage.tyj_jiangling_shadraw++;
                                    }
                                }
                                player.addTempSkill('tyj_tongji_buff');
                                player.addTempSkill('tyj_jiangling_remove');
                                player.markSkill('tyj_tongji_buff');
                                player.playerfocus(2000);
                            },
                            subSkill: {
                                remove: {
                                    forced: true,
                                    charlotte: true,
                                    onremove(player) {
                                        if (player.storage.tyj_jiangling_bonus && player.storage.tyj_jiangling_bonus > 0) {
                                            if (player.hp - player.storage.tyj_jiangling_bonus > 1) {
                                                player.changeHp(-player.storage.tyj_jiangling_bonus);
                                            } else {
                                                if (player.hp > 1) {
                                                    player.changeHp(1 - player.hp);
                                                }
                                            }
                                            if (player.maxHp - player.storage.tyj_jiangling_bonus > 1) {
                                                player.loseMaxHp(player.storage.tyj_jiangling_bonus);
                                            } else {
                                                if (player.maxHp > 1) {
                                                    player.loseMaxHp(player.maxHp - 1);
                                                }
                                            }
                                        }
                                        delete player.storage.tyj_jiangling_bonus;
                                        delete player.storage.tyj_jiangling_shadamage;
                                        delete player.storage.tyj_jiangling_shatarget;
                                        delete player.storage.tyj_jiangling_shadraw;
                                        var num = lib.skill.tyj_tongji.getTongjiCount(player);
                                        if (num <= 0) {
                                            player.unmarkSkill('tyj_tongji_buff');
                                        }
                                    },
                                },
                            },
                        },
