                        tyj_tachen: {
                            enable: 'phaseUse',
                            filter(event, player) {
                                if (
                                    player.countCards('h', function (card) {
                                        return get.color(card, player) == 'red';
                                    }) ==
                                    player.countCards('h', function (card) {
                                        return get.color(card, player) == 'black';
                                    })
                                )
                                    return false;
                                var num = 0;
                                game.getGlobalHistory(
                                    'cardMove',
                                    function (evt) {
                                        if (evt == event || evt.parent == event || (evt.name != 'lose' && evt.name != 'cardsDiscard')) return false;
                                        if (evt.name == 'lose' && evt.position != ui.discardPile) return false;
                                        for (var i = 0; i < evt.cards.length; i++) {
                                            var card = evt.cards[i];
                                            if (get.type(evt.cards[i]) == 'basic' && get.color(evt.cards[i]) == 'red') num++;
                                        }
                                    },
                                    event,
                                );
                                return (player.getStat('skill').tyj_tachen || 0) < Math.max(1, num); //(Math.max(3,num)+1);
                            },
                            content() {
                                'step 0';
                                player
                                    .chooseControl(['红色', '黑色'])
                                    .set('prompt', '选择将一种颜色的手牌调整至与另一种数量相同')
                                    .set('ai', function () {
                                        return ['红色', '黑色'].randomGet();
                                    });
                                ('step 1');
                                if (result.control) {
                                    var numb = player.getCards('h', function (card) {
                                        return get.color(card, player) == 'black';
                                    }).length;
                                    var numr = player.getCards('h', function (card) {
                                        return get.color(card, player) == 'red';
                                    }).length;
                                    if (result.control == '红色') {
                                        if (numr > numb) {
                                            player.chooseToDiscard(Math.max(numr - numb) || 1, { color: 'red' });
                                            event.num = Math.max(numr - numb);
                                            event.choosejudge = true;
                                        } else {
                                            var list = [];
                                            for (var i = 0; i < numb - numr; i++) {
                                                var cardsx = get.cardPile(function (card) {
                                                    return get.color(card) == 'red' && !list.includes(card);
                                                });
                                                if (cardsx) {
                                                    list.push(cardsx);
                                                }
                                            }
                                            if (list.length) {
                                                player.gain(list, 'draw');
                                                event.num = list.length;
                                            }
                                        }
                                    } else {
                                        if (numb > numr) {
                                            player.chooseToDiscard(Math.max(numb - numr) || 1, { color: 'black' });
                                            event.num = Math.max(numb - numr);
                                            event.choosejudge = true;
                                        } else {
                                            var list = [];
                                            for (var i = 0; i < numr - numb; i++) {
                                                var cardsx = get.cardPile(function (card) {
                                                    return get.color(card) == 'black' && !list.includes(card);
                                                });
                                                if (cardsx) {
                                                    list.push(cardsx);
                                                }
                                            }
                                            if (list.length) {
                                                player.gain(list, 'draw');
                                                event.num = list.length;
                                            }
                                        }
                                    }
                                } else {
                                    event.finish();
                                }
                                ('step 2');
                                if (event.num > 0) {
                                    event.num--;
                                    event.judgestr = get.translation('shandian');
                                    if (event.choosejudge) {
                                        player.chooseTarget(1, true, '踏尘:令一名其他角色进行一次【闪电】判定', lib.filter.notMe).set('ai', function (target) {
                                            return -get.attitude(player, target);
                                        });
                                    } else {
                                        event.judgestr = get.translation('shandian');
                                        player.judge(lib.card.shandian.judge, event.judgestr).judge2 = lib.card.shandian.judge2;
                                    }
                                } else event.finish();
                                ('step 3');
                                if (event.choosejudge) {
                                    if (result && result.targets) {
                                        event.judgestr = get.translation('shandian');
                                        event.currenttarget = result.targets[0];
                                        result.targets[0].judge(lib.card.shandian.judge, event.judgestr).judge2 = lib.card.shandian.judge2;
                                    }
                                } else {
                                    var name = 'shandian';
                                    if (event.cancelled && !event.direct) {
                                        if (lib.card[name].cancel) {
                                            var next = game.createEvent(name + 'Cancel');
                                            next.setContent(lib.card[name].cancel);
                                            next.cards = [];
                                            next.card = { name: name };
                                            next.player = player;
                                        }
                                    } else {
                                        var next = game.createEvent(name);
                                        next.setContent(function () {
                                            if (result.bool == false) {
                                                player.damage(3, 'thunder', 'nosource');
                                            }
                                        });
                                        next._result = result;
                                        next.cards = [];
                                        next.card = { name: name };
                                        next.player = player;
                                    }
                                    event.goto(2);
                                }
                                ('step 4');
                                var name = 'shandian';
                                if (event.cancelled && !event.direct) {
                                    if (lib.card[name].cancel) {
                                        var next = game.createEvent(name + 'Cancel');
                                        next.setContent(lib.card[name].cancel);
                                        next.cards = [];
                                        next.card = { name: name };
                                        next.player = event.currenttarget;
                                    }
                                } else {
                                    var target = event.currenttarget;
                                    var next = game.createEvent(name);
                                    next.setContent(function () {
                                        if (result.bool == false) {
                                            player.damage(3, 'thunder', 'nosource');
                                        }
                                    });
                                    next._result = result;
                                    next.cards = [];
                                    next.card = { name: name };
                                    next.player = event.currenttarget;
                                }
                                event.goto(2);
                            },
                        },
